@IsTest private class BindStaticField62 {
@IsTest static void observe(){
List<Account> rows=[SELECT Id FROM Account WHERE Name=:AbsentFilter.name];
}
}

@IsTest private class BindStaticCall62 {
@IsTest static void observe(){
List<Account> rows=[SELECT Id FROM Account WHERE Name=:AbsentFilter.value()];
}
}

@IsTest private class BindDynamicText62 {
@IsTest static void observe(){
try { Database.query('SELECT Id FROM Account WHERE Name=:AbsentFilter.name'); } catch(Exception e) { System.assert(false,'OBS|'+e.getTypeName()+': '+e.getMessage()); }
}
}

@IsTest private class BindDynamicMap62 {
@IsTest static void observe(){
List<SObject> rows=Database.queryWithBinds('SELECT Id FROM Account WHERE Name=:needle',new Map<String,Object>{'needle'=>AbsentFilter.name},AccessLevel.SYSTEM_MODE);
}
}

@IsTest private class BindDynamicKey62 {
@IsTest static void observe(){
List<SObject> rows=Database.queryWithBinds('SELECT Id FROM Account WHERE Name=:needle',new Map<String,Object>{'needle'=>'synthetic-missing'},AccessLevel.USER_MODE);System.assert(false,'OBS|'+rows.size());
}
}

@IsTest private class BindLocalShadow62 {
@IsTest static void observe(){
Account AbsentFilter=new Account(Name='synthetic-missing');List<Account> rows=[SELECT Id FROM Account WHERE Name=:AbsentFilter.Name];System.assert(false,'OBS|'+rows.size());
}
}

